import org.jsoup.nodes.Document;
import org.jsoup.nodes.TextNode;
import org.junit.Assert;
import org.junit.Test;

import java.io.IOException;

public class TextNodeTest {

    @Test
    public void textNodeConstructorTest() {
        TextNode textNode = new TextNode("Hello");
        Assert.assertEquals("Hello", textNode.text());
    }

    @Test
    public void nodeNameTest() {
        TextNode textNode = new TextNode("Hello");
        Assert.assertEquals("#text", textNode.nodeName());
    }

    @Test
    public void textSetterTest() {
        TextNode textNode = new TextNode("Hello");
        TextNode updatedNode = textNode.text("World");
        Assert.assertEquals("World", updatedNode.text());
    }

    @Test
    public void getWholeTextTest() {
        TextNode textNode = new TextNode("Hello World");
        Assert.assertEquals("Hello World", textNode.getWholeText());
    }

    @Test
    public void isBlankTest() {
        TextNode textNode = new TextNode("");
        Assert.assertTrue(textNode.isBlank());
    }

    @Test
    public void splitTextTest() {
        TextNode textNode = new TextNode("Hello World");
        TextNode newTextNode = textNode.splitText(5);
        Assert.assertEquals(" World", newTextNode.text());
    }

    @Test
    public void outerHtmlHeadTest() throws IOException {
        TextNode textNode = new TextNode("Hello");
        StringBuilder accum = new StringBuilder();
        textNode.outerHtmlHead(accum, 0, new Document.OutputSettings());
        Assert.assertEquals("Hello", accum.toString());
    }

    @Test
    public void outerHtmlTailTest() {
        TextNode textNode = new TextNode("Hello");
        StringBuilder accum = new StringBuilder();
        textNode.outerHtmlTail(accum, 0, new Document.OutputSettings());
        Assert.assertEquals("", accum.toString());
    }

    @Test
    public void cloneTest() {
        TextNode textNode = new TextNode("Hello");
        TextNode clonedNode = textNode.clone();
        Assert.assertNotSame(textNode, clonedNode);
        Assert.assertEquals(textNode.text(), clonedNode.text());
    }

    @Test
    public void createFromEncodedTest() {
        TextNode textNode = TextNode.createFromEncoded("SGVsbG8=", "UTF-8");
        Assert.assertEquals("Hello", textNode.text());
    }

    @Test
    public void normaliseWhitespaceTest() {
        String normalisedWhitespace = TextNode.normaliseWhitespace("Hello  World");
        Assert.assertEquals("Hello World", normalisedWhitespace);
    }

    @Test
    public void stripLeadingWhitespaceTest() {
        String strippedText = TextNode.stripLeadingWhitespace("  Hello");
        Assert.assertEquals("Hello", strippedText);
    }

    @Test
    public void lastCharIsWhitespaceTest() {
        boolean lastCharIsWhitespace = TextNode.lastCharIsWhitespace(new StringBuilder("Hello "));
        Assert.assertTrue(lastCharIsWhitespace);
    }
}
